import { ComparisonGroup } from "./types";

const STORAGE_KEY = "etf-backtest-groups-v1";

export function loadGroups(): ComparisonGroup[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveGroups(groups: ComparisonGroup[]): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(groups));
}

export function upsertGroup(group: ComparisonGroup): ComparisonGroup[] {
  const groups = loadGroups();
  const idx = groups.findIndex((g) => g.id === group.id);
  if (idx >= 0) {
    groups[idx] = group;
  } else {
    groups.push(group);
  }
  saveGroups(groups);
  return groups;
}

export function deleteGroup(id: string): ComparisonGroup[] {
  const groups = loadGroups().filter((g) => g.id !== id);
  saveGroups(groups);
  return groups;
}

export function newGroupId(): string {
  return `grp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}
